from queueing import payload

def submit(owner, enqueue, batch_size=20):
    if batch_size is True or batch_size is False:
        raise ValueError("batch_size must be an integer, not a bool")
    if not isinstance(batch_size, int) or batch_size < 1 or batch_size > 100:
        raise ValueError("batch_size must be an integer between 1 and 100")
    return enqueue(payload(owner, batch_size))

def execute(task, process):
    batch_size = task.get("batch_size", 20)
    return process(task["owner"], batch_size)

import api
import queueing
import worker

def test_submit_default_batch_size():
    """Test that submit defaults to batch_size=20"""
    result = api.submit("owner1", lambda x: x)
    assert result == {"owner": "owner1", "batch_size": 20}

def test_submit_explicit_batch_size():
    """Test that submit accepts explicit batch_size"""
    result = api.submit("owner2", lambda x: x, batch_size=50)
    assert result == {"owner": "owner2", "batch_size": 50}

